def _tag_keys(tags):
    """Extract the key set from `DAG.tags` regardless of YAML shape.

    Accepts:
    - `list[str]` of `key:value` strings (RFD 0011 §6 canonical form)
    - `list[dict]` (legacy dag-factory shape)
    - `dict` (legacy blueprint shape)
    """
    keys = set()
    if isinstance(tags, dict):
        keys.update(tags.keys())
        return keys
    for entry in tags or ():
        if isinstance(entry, dict):
            keys.update(entry.keys())
        elif isinstance(entry, str) and ":" in entry:
            keys.add(entry.split(":", 1)[0])
    return keys


def _tag_value(tags, key):
    """Extract value for `key` from `DAG.tags` in any of the accepted shapes."""
    if isinstance(tags, dict):
        return tags.get(key)
    prefix = f"{key}:"
    for entry in tags or ():
        if isinstance(entry, dict) and key in entry:
            return entry[key]
        if isinstance(entry, str) and entry.startswith(prefix):
            return entry[len(prefix):]
    return None


